//! Fluid font sizes; every expected value was produced by WordPress 7.1.5.
//!
//! Generated by `.superpowers/gen_fluid.py`; edit the generator, not the cases.

mod support;

use std::rc::Rc;

use speedyspec_hooks::{Key, Value};
use speedyspec_wp_theme_json::presets::fluid::{
    FluidArgs, FluidFontSize, computed_fluid_typography_value, typography_value_and_unit,
};
use speedyspec_wp_theme_json::{MemoryGlobalSettings, RecordedDiagnostics};
use support::{assert_php_same as assert_php_eq, json, opt};

fn fluid(global: Value) -> (FluidFontSize, Rc<RecordedDiagnostics>) {
    let notices = Rc::new(RecordedDiagnostics::default());
    (
        FluidFontSize {
            global: Rc::new(MemoryGlobalSettings::new(global)),
            diagnostics: notices.clone(),
        },
        notices,
    )
}

fn pair(data: Value, notices: Vec<String>) -> Value {
    let notices = Value::Array(
        notices
            .into_iter()
            .enumerate()
            .map(|(i, n)| (Key::Int(i as i64), Value::Str(n)))
            .collect(),
    );
    Value::Array(vec![(Key::Int(0), data), (Key::Int(1), notices)])
}

#[test]
fn value_and_unit_0_none() {
    let actual = {
        let (fluid, notices) = fluid(Value::Array(Vec::new()));
        let r = typography_value_and_unit(&json(r##""10""##), "", &*fluid.diagnostics)
            .map_or(Value::Null, |v| v.to_value());
        pair(r, notices.notices.borrow().clone())
    };
    assert_php_eq(&actual, &json(r##"[{"unit":"px","value":10.0},[]]"##));
}

