#[test]
fn global_settings_fill_missing_keys() {
    let actual = {
        let (fluid, notices) = fluid(json(
            r##"{"typography":{"fluid":true},"layout":{"wideSize":"1000px"}}"##,
        ));
        let r = fluid.value(&json(r##"{"size":"2rem"}"##), &json("[]"));
        pair(r, notices.notices.borrow().clone())
    };
    assert_php_eq(
        &actual,
        &json(r##"["clamp(1.25rem, 1.25rem + ((1vw - 0.2rem) * 1.765), 2rem)",[]]"##),
    );
}

#[test]
fn given_settings_win_over_global() {
    let actual = {
        let (fluid, notices) = fluid(json(r##"{"typography":{"fluid":true}}"##));
        let r = fluid.value(
            &json(r##"{"size":"2rem"}"##),
            &json(r##"{"typography":{"fluid":false}}"##),
        );
        pair(r, notices.notices.borrow().clone())
    };
    assert_php_eq(&actual, &json(r##"["2rem",[]]"##));
}
